import { Response as ExpressResponse } from 'express';
import { getRepository } from 'typeorm';
import { OrderEntity } from '../infrastructure/OrderEntity';

export class PlaceOrderInteractor {
  // Returns HTTP response directly from the use case
  async execute(customerId: string, items: any[], res: ExpressResponse): Promise<void> {
    // Directly uses ORM inside the interactor
    const repo = getRepository(OrderEntity);
    const order = repo.create({ customerId, items, status: 'pending' });
    await repo.save(order);
    // Delivers result directly to the HTTP response
    res.status(201).json({ orderId: order.id });
  }
}

